import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {test} from 'node:test';
import {p256} from '@noble/curves/nist.js';
import {parseProductSessionRegistry,productPlatformBinding} from '../src/product-session-registry.js';
import {ProductSessionAuthority,createProductSessionRequest,signProductSessionApproval,signProductSessionChallenge} from '../src/product-session-v2.js';
const registry=JSON.parse(readFileSync(new URL('../product-session-registry.json',import.meta.url),'utf8'));
const legacyScopes=['account:read','profile:link','social.contacts','social.messaging','social.profile'];
const at=new Date('2026-10-02T00:00:00.000Z'), device=Buffer.alloc(32,7);
const input={productId:'social',platform:'web',deviceId:'a'.repeat(43),deviceKey:Buffer.from(p256.getPublicKey(device,true)).toString('base64url'),purpose:'Explicit Social permission',nonce:'b'.repeat(43),state:'c'.repeat(43)};
function finish(r,requested){const a=new ProductSessionAuthority(r);const request=createProductSessionRequest(r,{...input,scopes:requested},at);const approval=signProductSessionApproval(r,request,{accountSecret:'1'.padStart(64,'0'),scopes:request.scopes,expiresAt:request.expiresAt},at);const challenge=a.issueChallenge({request,approval,challenge:'d'.repeat(43)},at);return{authority:a,request,approval,session:a.complete({request,approval,completion:signProductSessionChallenge(challenge,device.toString('base64url'))},at)};}
function context(s,requiredScopes){return {...Object.fromEntries(['chainId','productId','clientId','platform','applicationId','bundleId','packageId','origin','callback','account','deviceId','deviceKey'].map(k=>[k,s[k]])),requiredScopes};}
test('Social registers only existing route scopes, exact tuple and original short lifetime',()=>{const p=parseProductSessionRegistry(registry).products.find(p=>p.productId==='social');assert.deepEqual(p.scopes,[...legacyScopes,'social.feed','social.ai'].sort());assert.equal(p.sessionDurationSeconds,240);assert.equal(p.evmCompatible,false);for(const platform of ['web','android','ios','linux','macos','windows']){const b=productPlatformBinding(registry,'social',platform);assert.equal(b.applicationId,platform==='web'?'com.ynx.social.web':'com.ynx.social');assert.equal(b.origin,platform==='web'?'https://social.ynxweb4.com':`app://${platform}/com.ynx.social`);}for(const scope of ['social.media','social.follows','social.groups','social.local-ai','social.*'])assert.throws(()=>createProductSessionRequest(registry,{...input,scopes:[scope]},at));});
test('new feed and cloud AI are separate explicit signed approvals; messaging cannot authorize them',()=>{for(const approved of ['social.messaging','social.feed','social.ai']){const {authority,session}=finish(registry,[approved]);for(const required of ['social.feed','social.ai']){if(approved===required)assert.equal(authority.introspect(session.sessionBinding,context(session,[required]),at).active,true);else assert.throws(()=>authority.introspect(session.sessionBinding,context(session,[required]),at),e=>e.code==='INVALID_SCOPES'||e.code==='SCOPE_WIDENING');}}});
test('cold legacy Social grant remains original scopes and cannot gain feed or cloud AI',()=>{const old=structuredClone(registry);old.products.find(p=>p.productId==='social').scopes=legacyScopes;const {authority,session}=finish(old,legacyScopes);const recovered=new ProductSessionAuthority(registry,authority.snapshot());assert.deepEqual(session.scopes,legacyScopes);assert.equal(recovered.introspect(session.sessionBinding,context(session,['social.messaging']),at).active,true);for(const required of ['social.feed','social.ai'])assert.throws(()=>recovered.introspect(session.sessionBinding,context(session,[required]),at),e=>e.code==='INVALID_SCOPES'||e.code==='SCOPE_WIDENING');});
